<?php
require __DIR__.'/../app/bootstrap.php';
require_once __DIR__.'/../app/layout.php';
require_once __DIR__.'/../app/landing_theme_parity_v1110.php';
$me=current_user();if(!$me||!(has_permission('settings.manage',$me)||has_permission('updates.manage',$me))){http_response_code(403);exit('Forbidden');}
$tid=sk1110_tid();$flash='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=(string)($_POST['action']??'');if($a==='safe'){try{db()->prepare('UPDATE landing_theme_parity_v1110 SET inject_missing_sections=0,updated_at=NOW() WHERE tenant_id=?')->execute([$tid]);$flash='Safe mode enabled: current landing theme stays live without injected missing sections.';}catch(Throwable $e){$flash=$e->getMessage();}}elseif($a==='full'){try{db()->prepare('UPDATE landing_theme_parity_v1110 SET enabled=1,inject_missing_sections=1,updated_at=NOW() WHERE tenant_id=?')->execute([$tid]);$flash='Full async parity enabled.';}catch(Throwable $e){$flash=$e->getMessage();}}}
$cfg=sk1110_config($tid);page_start('Landing Recovery',true);?>
<div style="max-width:900px;margin:20px auto;padding:20px"><h2>Landing Page Recovery v11.1.2</h2><?php if($flash):?><p style="padding:12px;background:#eef6ff;border-radius:10px"><?=htmlspecialchars($flash)?></p><?php endif;?><p>The v11.1.0 nested output-buffer issue has been removed. Missing Smart Homepage sections now load asynchronously after the current Landing Theme HTML is already visible.</p><p><b>Full async parity:</b> <?=!empty($cfg['inject_missing_sections'])?'ON':'OFF'?></p><form method="post" style="display:flex;gap:10px;flex-wrap:wrap"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(csrf_token(),ENT_QUOTES)?>"><button name="action" value="full">Enable Full Async Parity</button><button name="action" value="safe">Safe Mode (No Missing Sections)</button></form><p style="margin-top:18px"><a href="/admin/landing-theme-sync.php">Landing Theme Sync Settings</a> · <a href="/">Open Website</a></p></div><?php require __DIR__.'/../app/end.php';?>